static void FS_CheckFilenameIsMutable( const char *filename, /* <=== FS_CheckFilenameIsMutable */ 
		const char *function )
{
	// Check if the filename ends with the library, QVM, or pk3 extension
	if( COM_CompareExtension( filename, DLL_EXT )
		|| COM_CompareExtension( filename, ".qvm" )
		|| COM_CompareExtension( filename, ".pk3" ) )
	{
		Com_Error( ERR_FATAL, "%s: Not allowed to manipulate '%s' due "
			"to %s extension", function, filename, COM_GetExtension( filename ) );
	}
}

int Q_stricmp (const char *s1, const char *s2) /* <=== Q_stricmp */ 
{
	return Q_strncasecmp (s1, s2, 99999);
}

int QDECL Com_sprintf(char *dest, int size, const char *fmt, ...) /* <=== Com_sprintf */ 
{
	int		len;
	va_list		argptr;

	va_start (argptr,fmt);
	len = Q_vsnprintf(dest, size, fmt, argptr);
	va_end (argptr);

	if(len >= size)
		Com_Printf("Com_sprintf: Output length %d too short, require %d bytes.\n", size, len + 1);

	return len;
}

